import re
from datetime import datetime

_DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DIGITS = "0123456789"


def _is_digits(s):
    return s != "" and all(c in _DIGITS for c in s)


def _parse_updated(value):
    s = value.strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            pass
    raise ValueError(f"Unrecognized 'updated' value: {value!r}")


def _normalize_email(raw):
    s = raw
    start = s.find("<")
    if start != -1:
        end = s.find(">", start + 1)
        if end != -1:
            s = s[start + 1:end]
    s = s.strip().lower()
    if s.count("@") != 1:
        return s
    local, domain = s.split("@")
    if domain in _GMAIL_DOMAINS:
        local = local.replace(".", "").split("+", 1)[0]
        domain = "gmail.com"
    return f"{local}@{domain}"


def _is_valid_email(email):
    if email.count("@") != 1:
        return False
    local, domain = email.split("@")
    return (
        local != ""
        and "." in domain
        and not domain.startswith(".")
        and not domain.endswith(".")
    )


def _normalize_phone(raw):
    s = raw.lower()
    cut = len(s)
    for marker in ("x", "ext", "#"):
        idx = s.find(marker)
        if idx != -1:
            cut = min(cut, idx)
    digits = "".join(c for c in s[:cut] if c in _DIGITS)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    return digits


def _is_valid_phone(digits):
    return len(digits) == 10 and digits[0] not in "01"


def _normalize_zip(raw):
    s = raw.strip()
    m = re.fullmatch(r"([0-9]{4,5})-[0-9]{4}", s)  # ZIP+4, allowing Excel-trimmed 4-digit prefix
    if m:
        s = m.group(1)
    if len(s) == 4 and _is_digits(s):
        s = "0" + s
    return s if len(s) == 5 and _is_digits(s) else ""


def _normalize_name(raw):
    s = raw.strip()
    if s.isupper() or s.islower():
        return s.title()
    return s


def _normalize_tags(raw):
    return {p.strip().lower() for p in re.split(r"[;,]", raw) if p.strip()}


def _pick(members, field):
    """Choose the value for `field` from the group's rows, per the priority rules:
    manual source first, then most recent `updated`, then earliest input row."""
    cands = [m for m in members if m[field]]
    if not cands:
        return ""
    # Stable sorts applied from lowest to highest priority key.
    cands.sort(key=lambda m: m["idx"])
    cands.sort(key=lambda m: m["updated"], reverse=True)
    cands.sort(key=lambda m: not m["manual"])
    return cands[0][field]


def dedupe_contacts(rows):
    # 1. Normalize every row and drop rows with neither a valid email nor a valid phone.
    records = []
    for idx, row in enumerate(rows):
        email = _normalize_email(row["email"])
        if not _is_valid_email(email):
            email = ""
        phone = _normalize_phone(row["phone"])
        if not _is_valid_phone(phone):
            phone = ""
        if not email and not phone:
            continue

        source = row["source"].strip().lower()
        records.append({
            "idx": idx,
            "first_name": _normalize_name(row["first_name"]),
            "last_name": _normalize_name(row["last_name"]),
            "zip": _normalize_zip(row["zip"]),
            "email": email,
            "phone": phone,
            "source": source,
            "manual": source == "manual",
            "tags": _normalize_tags(row["tags"]),
            "opted_out": row["opted_out"].strip().lower() in ("y", "yes", "true", "1"),
            "updated": _parse_updated(row["updated"]),
        })

    # 2. Union-find over records. Rows sharing a valid email, or a valid phone plus
    #    a non-empty last name (casefolded), are the same person; unions are transitive.
    parent = list(range(len(records)))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[max(ra, rb)] = min(ra, rb)

    first_by_email = {}
    first_by_phone_last = {}
    for pos, rec in enumerate(records):
        if rec["email"]:
            key = rec["email"]
            if key in first_by_email:
                union(first_by_email[key], pos)
            else:
                first_by_email[key] = pos
        if rec["phone"] and rec["last_name"]:
            key = (rec["phone"], rec["last_name"].casefold())
            if key in first_by_phone_last:
                union(first_by_phone_last[key], pos)
            else:
                first_by_phone_last[key] = pos

    # 3. Group records by root. Positions are already in input order, so each
    #    group's first element is its earliest row; sort groups by that.
    groups = {}
    for pos in range(len(records)):
        groups.setdefault(find(pos), []).append(pos)
    ordered_groups = sorted(groups.values(), key=lambda g: g[0])

    # 4. Build one output dict per person.
    result = []
    for group in ordered_groups:
        members = [records[p] for p in group]
        person = {}
        for field in ("first_name", "last_name", "zip", "email", "phone", "source"):
            person[field] = _pick(members, field)
        person["tags"] = ";".join(sorted(set().union(*(m["tags"] for m in members))))
        person["opted_out"] = "Y" if any(m["opted_out"] for m in members) else "N"
        person["updated"] = max(m["updated"] for m in members).strftime("%Y-%m-%d")
        result.append(person)

    return result
